
SELECT 'core.inventory_master' AS table_name, 'opening_stock < 0' AS validation_check, COUNT(*) AS invalid_rows FROM core.inventory_master WHERE opening_stock < 0 UNION ALL SELECT 'core.inventory_master', 'reorder_level < 0', COUNT(*) FROM core.inventory_master WHERE reorder_level < 0 UNION ALL SELECT 'core.inventory_master', 'safety_stock < 0', COUNT(*) FROM core.inventory_master WHERE safety_stock < 0 UNION ALL SELECT 'core.inventory_snapshots', 'available_stock < 0', COUNT(*) FROM core.inventory_snapshots WHERE available_stock < 0 UNION ALL SELECT 'core.inventory_snapshots', 'reserved_stock < 0', COUNT(*) FROM core.inventory_snapshots WHERE reserved_stock < 0 UNION ALL SELECT 'core.inventory_snapshots', 'reorder_level < 0', COUNT(*) FROM core.inventory_snapshots WHERE reorder_level < 0 UNION ALL SELECT 'core.product_suppliers', 'unit_cost < 0', COUNT(*) FROM core.product_suppliers WHERE unit_cost < 0 UNION ALL SELECT 'core.suppliers', 'average_lead_time_days < 0', COUNT(*) FROM core.suppliers WHERE average_lead_time_days < 0 UNION ALL SELECT 'core.supplier_performance', 'ordered_quantity <= 0', COUNT(*) FROM core.supplier_performance WHERE ordered_quantity <= 0 UNION ALL SELECT 'core.supplier_performance', 'received_quantity < 0', COUNT(*) FROM core.supplier_performance WHERE received_quantity < 0 UNION ALL SELECT 'core.supplier_performance', 'accepted_quantity < 0', COUNT(*) FROM core.supplier_performance WHERE accepted_quantity < 0 UNION ALL SELECT 'core.supplier_performance', 'accepted_quantity > received_quantity', COUNT(*) FROM core.supplier_performance WHERE accepted_quantity > received_quantity UNION ALL SELECT 'core.supplier_performance', 'expected_delivery_date < order_date', COUNT(*) FROM core.supplier_performance WHERE expected_delivery_date < order_date UNION ALL SELECT 'core.supplier_performance', 'actual_delivery_date < order_date', COUNT(*) FROM core.supplier_performance WHERE actual_delivery_date < order_date ORDER BY table_name, validation_check;
